import * as THREE from './vendor/three.module.js';
import {COLORS,TIERS} from './core.js';

const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
export function createTable(host,items,{demo=false,concealed=false}={}){
 let renderer;
 try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});}catch{return fallback(host,items,concealed);}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.setClearColor(0x000000,0);
 renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;
 host.append(renderer.domElement);renderer.domElement.setAttribute('aria-hidden','true');
 const scene=new THREE.Scene();const camera=new THREE.OrthographicCamera(-5,5,3,-3,.1,40);camera.position.set(0,2.6,12);camera.lookAt(0,0,0);
 scene.add(new THREE.HemisphereLight(0xfff8e6,0x305a49,2.8));
 const light=new THREE.DirectionalLight(0xfff5dc,3.2);light.position.set(-3,5,8);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-7,right:7,top:5,bottom:-5});light.shadow.bias=-.001;scene.add(light);
 const shadow=new THREE.Mesh(new THREE.PlaneGeometry(30,20),new THREE.ShadowMaterial({opacity:.23}));shadow.position.z=-.22;shadow.receiveShadow=true;scene.add(shadow);
 const w=1.52,h=2.18,r=.09;const shape=new THREE.Shape();shape.moveTo(-w/2+r,-h/2);shape.lineTo(w/2-r,-h/2);shape.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);shape.lineTo(w/2,h/2-r);shape.quadraticCurveTo(w/2,h/2,w/2-r,h/2);shape.lineTo(-w/2+r,h/2);shape.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);shape.lineTo(-w/2,-h/2+r);shape.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);
 const geo=new THREE.ExtrudeGeometry(shape,{depth:.035,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.012,bevelThickness:.009,curveSegments:8});
 const faceGeo=new THREE.PlaneGeometry(w-.025,h-.025);const bodyMat=new THREE.MeshStandardMaterial({color:0xf4f0e3,roughness:.78});
 const cards=items.map((item,i)=>{const g=new THREE.Group();const body=new THREE.Mesh(geo,bodyMat);body.castShadow=true;g.add(body);const face=new THREE.Mesh(faceGeo,new THREE.MeshStandardMaterial({map:texture(item,i,concealed),roughness:.85}));face.position.z=.047;g.add(face);g.position.set((i-2)*1.76,-.1,0);g.rotation.z=demo?(i-2)*-.075:((i%2)*2-1)*.018;g.userData={item,face,targetX:g.position.x,targetR:g.rotation.z};scene.add(g);return g;});
 let alive=true,frame=0,last=performance.now(),pointer=0;const raycaster=new THREE.Raycaster();let hover=-1;
 function resize(){const width=host.clientWidth,height=host.clientHeight;if(!width||!height)return;renderer.setSize(width,height,false);const aspect=width/height;const vw=demo?9.55:9.4;camera.left=-vw/2;camera.right=vw/2;camera.top=vw/aspect/2;camera.bottom=-vw/aspect/2;camera.updateProjectionMatrix();}
 const observer=new ResizeObserver(resize);observer.observe(host);resize();
 function move(e){const rect=host.getBoundingClientRect();pointer=(e.clientX-rect.left)/rect.width-.5;raycaster.setFromCamera(new THREE.Vector2(pointer*2,-((e.clientY-rect.top)/rect.height)*2+1),camera);const hits=raycaster.intersectObjects(cards,true);hover=hits.length?cards.indexOf(hits[0].object.parent):-1;}
 host.addEventListener('pointermove',move);const leave=()=>{pointer=0;hover=-1;};host.addEventListener('pointerleave',leave);
 function tick(now){if(!alive)return;frame=requestAnimationFrame(tick);if(document.hidden)return;const dt=Math.min((now-last)/1000,.1);last=now;const a=reduced?1:1-Math.exp(-dt*10);cards.forEach((c,i)=>{c.position.x+=(c.userData.targetX-c.position.x)*a;c.position.y+=((hover===i&&!reduced?.08:-.1)-c.position.y)*a;c.rotation.y+=(0-c.rotation.y)*a;c.rotation.z+=(c.userData.targetR-c.rotation.z)*a;});camera.position.x+=(pointer*.15-camera.position.x)*a;camera.lookAt(0,0,0);renderer.render(scene,camera);}
 frame=requestAnimationFrame(tick);
 return {update(next,{revealed=5,flip=false}={}){next.forEach((item,i)=>{const card=cards.find(c=>c.userData.item===item);if(!card)return;card.userData.targetX=(i-2)*1.76;card.userData.targetR=demo?(i-2)*-.075:((i%2)*2-1)*.018;card.userData.face.material.map.dispose();card.userData.face.material.map=texture(item,i,i>=revealed);card.userData.face.material.needsUpdate=true;if(flip&&i===revealed-1&&!reduced)card.rotation.y=-Math.PI*2;});},destroy(){alive=false;cancelAnimationFrame(frame);observer.disconnect();host.removeEventListener('pointermove',move);host.removeEventListener('pointerleave',leave);cards.forEach(c=>{c.userData.face.material.map.dispose();c.userData.face.material.dispose();});geo.dispose();faceGeo.dispose();bodyMat.dispose();shadow.geometry.dispose();shadow.material.dispose();light.shadow.map?.dispose();renderer.dispose();renderer.forceContextLoss();renderer.domElement.remove();}};
}
function texture(item,index,back){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=740;const ctx=canvas.getContext('2d');ctx.fillStyle=back?'#e5ed9b':'#f5f1e5';ctx.fillRect(0,0,512,740);ctx.strokeStyle=back?'#9eae78':'#d3d4c3';ctx.lineWidth=2;ctx.strokeRect(24,24,464,692);ctx.textAlign='left';ctx.fillStyle='#244336';ctx.font='600 20px sans-serif';ctx.fillText('BEST TO WORST',45,67);ctx.fillStyle='#718272';ctx.font='15px sans-serif';ctx.fillText('RANKING CARD',45,94);
 if(back){ctx.textAlign='center';ctx.fillStyle='#244336';ctx.font='900 135px "PingFang SC",sans-serif';ctx.fillText('?',256,345);ctx.font='20px sans-serif';ctx.fillText('RANK HIDDEN',256,435);ctx.font='14px sans-serif';ctx.fillText('BEST TO WORST',256,648);}else{ctx.fillStyle=COLORS[index];ctx.beginPath();ctx.arc(256,312,103,0,Math.PI*2);ctx.fill();ctx.fillStyle='#244336';ctx.textAlign='center';ctx.font='italic 118px Georgia,serif';ctx.fillText(String(index+1),250,350);ctx.font='700 37px "PingFang SC",sans-serif';const words=item.split(' ');const lines=[];let line='';for(const word of words){const candidate=line?line+' '+word:word;if(line&&ctx.measureText(candidate).width>420){lines.push(line);line=word;}else line=candidate;}if(line)lines.push(line);lines.forEach((text,i)=>ctx.fillText(text,256,480+i*53,420));ctx.textAlign='left';ctx.font='14px sans-serif';ctx.fillStyle='#73816c';ctx.fillText('FAVORITE → LEAST FAVORITE',45,653);ctx.textAlign='right';ctx.fillStyle='#294b3c';ctx.font='700 26px sans-serif';ctx.fillText(TIERS[index],465,693);COLORS.forEach((color,i)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(51+i*20,687,5,0,Math.PI*2);ctx.fill();});}
 const tex=new THREE.CanvasTexture(canvas);tex.colorSpace=THREE.SRGBColorSpace;tex.anisotropy=4;return tex;}
function fallback(host,items,concealed){host.innerHTML='<div class="fallback"></div>';const grid=host.firstChild;function update(next,{revealed=5}={}){grid.replaceChildren(...next.map((item,i)=>{const e=document.createElement('div');e.className='flat-card';e.textContent=i<revealed?`${i+1} · ${item}`:'Your guess?';return e;}));}update(items,{revealed:concealed?0:5});return {update,destroy(){host.replaceChildren();}};}
